CREATE TABLE achievements (
    achievement_id TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    description TEXT NOT NULL,
    unlock_type TEXT NOT NULL,
    unlock_threshold BIGINT NOT NULL,
    reward_xp   BIGINT NOT NULL DEFAULT 0,
    reward_coins BIGINT NOT NULL DEFAULT 0,
    reward_cosmetic_id TEXT,
    tier        TEXT NOT NULL DEFAULT 'common'
);

CREATE TABLE users (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email           TEXT NOT NULL UNIQUE,
    username        TEXT NOT NULL UNIQUE,
    full_name       TEXT NOT NULL,
    password_hash   TEXT NOT NULL,
    created_at      TEXT DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
    last_login      TEXT,
    api_key_encrypted TEXT,
    llm_provider    TEXT,
    llm_model       TEXT,
    llm_base_url    TEXT
, timezone TEXT NOT NULL DEFAULT 'UTC');

CREATE TABLE activity_log (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id  TEXT NOT NULL,
    mode        TEXT NOT NULL,
    action_type TEXT NOT NULL,
    content     TEXT,
    created_at  TEXT DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE arena_runs (
    id              TEXT PRIMARY KEY,                       -- the run_id handed to the client
    user_id         BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id      TEXT NOT NULL,                          -- the document the run goes through
    doc_hash        TEXT NOT NULL,
    difficulty      TEXT NOT NULL CHECK (difficulty IN ('easy', 'medium', 'hard', 'nightmare')),
    seed            BIGINT NOT NULL,                       -- the map of every act is derived from this
    acts_json       TEXT NOT NULL,                          -- [{title, topic}] x 3, extracted by the LLM at the start
    map_json        TEXT NOT NULL,                          -- the generated maps (a pure function of seed + acts)
    nemesis_ok      BIGINT NOT NULL DEFAULT 0,             -- weak-concept data existed at the start: nemesis nodes
    status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'won', 'lost', 'abandoned')),
    act             BIGINT NOT NULL DEFAULT 1,
    node_id         TEXT,                                   -- where the player stands (NULL = at the start of the act)
    visited_json    TEXT NOT NULL DEFAULT '[]',
    hearts          BIGINT NOT NULL,
    max_hearts      BIGINT NOT NULL,
    gold            BIGINT NOT NULL DEFAULT 0,
    relics_json     TEXT NOT NULL DEFAULT '[]',
    flags_json      TEXT NOT NULL DEFAULT '{}',             -- once-per-run relic state (phoenix_ash used ...)
    focus_cap       BIGINT NOT NULL DEFAULT 5,
    act_focus_bonus BIGINT NOT NULL DEFAULT 0,             -- rest "study": +1 Focus at the start of each battle this act
    pending_json    TEXT,                                   -- a choice the player must make (rest / shop / relic)
    battle_id       TEXT,                                   -- the fight in progress, if any
    depth           BIGINT NOT NULL DEFAULT 0,             -- nodes cleared
    battles_won     BIGINT NOT NULL DEFAULT 0,
    answered        BIGINT NOT NULL DEFAULT 0,             -- summed from the run's finished battles
    correct         BIGINT NOT NULL DEFAULT 0,
    score           BIGINT NOT NULL DEFAULT 0,
    rewards_json    TEXT,
    result_json     TEXT,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    finished_at     TEXT
);

CREATE TABLE arena_battles (
    id             TEXT PRIMARY KEY,                       -- the battle_id handed to the client
    user_id        BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id     TEXT NOT NULL,                          -- the document the battle is about
    doc_hash       TEXT NOT NULL,                          -- that document's content hash (part of the board key)
    topic          TEXT NOT NULL,
    difficulty     TEXT NOT NULL CHECK (difficulty IN ('easy', 'medium', 'hard', 'nightmare')),
    board_key      TEXT NOT NULL,
    boss_json      TEXT NOT NULL,                          -- the whole boss: persona, taunts, current_hp, phase, rage
    status         TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'won', 'lost')),
    phase          BIGINT NOT NULL DEFAULT 1,
    boss_hp        BIGINT NOT NULL,
    boss_max_hp    BIGINT NOT NULL,
    player_hp      BIGINT NOT NULL,
    player_max_hp  BIGINT NOT NULL,
    combo          BIGINT NOT NULL DEFAULT 0,
    max_combo      BIGINT NOT NULL DEFAULT 0,
    answered       BIGINT NOT NULL DEFAULT 0,
    correct        BIGINT NOT NULL DEFAULT 0,
    heals_used     BIGINT NOT NULL DEFAULT 0,
    fifty_used     BIGINT NOT NULL DEFAULT 0,
    active_ms      BIGINT NOT NULL DEFAULT 0,             -- time spent on questions, measured by the server
    current_seq    BIGINT,                                -- the question that is issued and not answered yet
    gen_attempts_1 BIGINT NOT NULL DEFAULT 0,             -- question batches generated per phase (bounded)
    gen_attempts_2 BIGINT NOT NULL DEFAULT 0,
    rewards_json   TEXT,                                   -- what the finish paid (NULL until finished)
    result_json    TEXT,                                   -- grade / accuracy / time of the finished battle
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    finished_at    TEXT
, mode TEXT NOT NULL DEFAULT 'quick' CHECK (mode IN ('quick', 'nemesis', 'expedition')), run_id TEXT REFERENCES arena_runs(id) ON DELETE CASCADE, focus BIGINT NOT NULL DEFAULT 0, focus_cap BIGINT NOT NULL DEFAULT 5, shield BIGINT NOT NULL DEFAULT 0, intent_json TEXT);

CREATE TABLE arena_personal_bests (
    user_id      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    board_key    TEXT NOT NULL,
    battle_id    TEXT NOT NULL,
    grade        TEXT NOT NULL,
    accuracy     BIGINT NOT NULL,
    time_seconds BIGINT NOT NULL,
    updated_at   TEXT NOT NULL,
    PRIMARY KEY (user_id, board_key)
);

CREATE TABLE arena_questions (
    battle_id    TEXT NOT NULL REFERENCES arena_battles(id) ON DELETE CASCADE,
    seq          BIGINT NOT NULL,                         -- 1, 2, 3 ... the order they are asked
    phase        BIGINT NOT NULL,
    concept_key  TEXT NOT NULL,                            -- normalised concept: a battle never asks one twice
    text_key     TEXT NOT NULL,                            -- normalised question text
    question_json TEXT NOT NULL,                           -- full question incl. correct_answer + explanation (server only)
    status       TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'issued', 'answered')),
    options_json TEXT,                                     -- the options in the shuffled order the player saw
    removed_json TEXT,                                     -- options hidden by a 50/50
    issued_at    TEXT,
    deadline_at  TEXT,
    answer       TEXT,
    correct      BIGINT,
    timed_out    BIGINT,
    answered_at  TEXT,
    outcome_json TEXT, move TEXT, timewarped BIGINT NOT NULL DEFAULT 0,                                     -- the stored result, returned again on a replay
    PRIMARY KEY (battle_id, seq)
);

CREATE TABLE arena_scores (
    battle_id    TEXT PRIMARY KEY REFERENCES arena_battles(id) ON DELETE CASCADE,
    board_key    TEXT NOT NULL,
    user_id      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    username     TEXT NOT NULL,
    topic        TEXT NOT NULL,
    topic_key    TEXT NOT NULL,                            -- normalised topic (lower-case, single spaces)
    difficulty   TEXT NOT NULL,
    doc_hash     TEXT NOT NULL,
    grade        TEXT NOT NULL,
    accuracy     BIGINT NOT NULL,                         -- 0-100, from the stored answers
    time_seconds BIGINT NOT NULL,                         -- from the server's own clock
    created_at   TEXT NOT NULL
);

CREATE TABLE champion_progress (
    user_id      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    champion_id  TEXT NOT NULL CHECK (champion_id IN ('kaien', 'asha', 'brak', 'mira', 'vex', 'thorne')),
    xp           BIGINT NOT NULL DEFAULT 0 CHECK (xp >= 0),
    level        BIGINT NOT NULL DEFAULT 1 CHECK (level BETWEEN 1 AND 10),
    battles      BIGINT NOT NULL DEFAULT 0,
    wins         BIGINT NOT NULL DEFAULT 0,
    updated_at   TEXT NOT NULL,
    PRIMARY KEY (user_id, champion_id)
);

CREATE TABLE concept_maps (
    doc_hash     TEXT NOT NULL,
    version      BIGINT NOT NULL,
    status       TEXT NOT NULL CHECK (status IN ('queued', 'running', 'ready', 'failed')),
    stage        TEXT,
    data_json    TEXT,
    error        TEXT,
    model        TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    PRIMARY KEY (doc_hash, version)
);

CREATE TABLE concept_mastery (
    user_id       BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    doc_hash      TEXT NOT NULL,
    concept_key   TEXT NOT NULL,                            -- normalised concept (question_key)
    concept       TEXT NOT NULL,                            -- as last written
    seen          BIGINT NOT NULL DEFAULT 0,
    correct       BIGINT NOT NULL DEFAULT 0,
    wrong_streak  BIGINT NOT NULL DEFAULT 0,
    last_seen_at  TEXT NOT NULL,
    last_wrong_at TEXT,
    PRIMARY KEY (user_id, doc_hash, concept_key)
);

CREATE TABLE courses (
    id           TEXT PRIMARY KEY,
    user_id      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    description  TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);

CREATE TABLE documents (
    id              TEXT PRIMARY KEY,
    user_id         BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    filename        TEXT NOT NULL,
    file_hash       TEXT NOT NULL,
    status          TEXT NOT NULL DEFAULT 'queued'
                    CHECK (status IN ('queued', 'reading', 'indexing', 'ready', 'failed', 'needs_reindex')),
    error           TEXT,
    chunks          BIGINT,
    embedding_model TEXT,
    index_path      TEXT,
    created_at      TEXT NOT NULL,
    last_used_at    TEXT NOT NULL
);

CREATE TABLE course_documents (
    course_id    TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
    document_id  TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    position     BIGINT NOT NULL DEFAULT 0,
    added_at     TEXT NOT NULL,
    PRIMARY KEY (course_id, document_id)
);

CREATE TABLE daily_action_counts (
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    action_date_utc TEXT NOT NULL,
    action_type TEXT NOT NULL,
    count       BIGINT NOT NULL DEFAULT 0,
    last_ts_utc TEXT,
    PRIMARY KEY (user_id, action_date_utc, action_type)
);

CREATE TABLE daily_quests (
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    quest_date_utc TEXT NOT NULL,
    quest_type  TEXT NOT NULL,
    target_count  BIGINT NOT NULL,
    current_count BIGINT NOT NULL DEFAULT 0,
    reward_xp     BIGINT NOT NULL,
    reward_coins  BIGINT NOT NULL,
    completed   BIGINT NOT NULL DEFAULT 0,
    claimed     BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, quest_date_utc, quest_type)
);

CREATE TABLE exams (
    id             TEXT PRIMARY KEY,
    user_id        BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id     TEXT NOT NULL,
    doc_hash       TEXT NOT NULL,
    doc_name       TEXT NOT NULL,
    length         BIGINT NOT NULL,
    difficulty     TEXT NOT NULL CHECK (difficulty IN ('easy', 'medium', 'hard', 'mixed')),
    topics_json    TEXT NOT NULL DEFAULT '[]',
    time_limit_s   BIGINT NOT NULL,
    started_at     TEXT NOT NULL,
    deadline       TEXT NOT NULL,
    submitted_at   TEXT,
    status         TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'graded')),
    score          BIGINT,
    total          BIGINT NOT NULL,
    accuracy       DOUBLE PRECISION,
    time_used_s    BIGINT,
    breakdown_json TEXT,
    auto_submitted BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE exam_answers (
    exam_id      TEXT NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    idx          BIGINT NOT NULL,
    answer       TEXT,
    flagged      BIGINT NOT NULL DEFAULT 0,
    correct      BIGINT,
    answered_at  TEXT NOT NULL,
    PRIMARY KEY (exam_id, idx)
);

CREATE TABLE exam_questions (
    exam_id        TEXT NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    idx            BIGINT NOT NULL,
    question       TEXT NOT NULL,
    options_json   TEXT NOT NULL,
    correct_answer TEXT NOT NULL,
    explanation    TEXT,
    concept        TEXT NOT NULL,
    difficulty     TEXT NOT NULL,
    PRIMARY KEY (exam_id, idx)
);

CREATE TABLE invite_codes (
    code         TEXT PRIMARY KEY,
    tier         TEXT NOT NULL CHECK (tier IN ('apprentice', 'scholar', 'sage', 'archmage')),
    days         BIGINT,
    max_uses     BIGINT NOT NULL DEFAULT 1,
    uses         BIGINT NOT NULL DEFAULT 0,
    note         TEXT,
    created_at   TEXT NOT NULL,
    expires_at   TEXT,
    revoked      BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE invite_redemptions (
    code         TEXT NOT NULL REFERENCES invite_codes(code) ON DELETE CASCADE,
    user_id      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    redeemed_at  TEXT NOT NULL,
    PRIMARY KEY (code, user_id)
);

CREATE TABLE leaderboard (
    TEXT        TEXT NOT NULL,
    topic       TEXT NOT NULL,
    difficulty  TEXT NOT NULL,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    username    TEXT NOT NULL,
    grade       TEXT,
    accuracy    BIGINT DEFAULT 0,
    time_seconds BIGINT DEFAULT 9999,
    PRIMARY KEY (TEXT, topic, difficulty, user_id)
);

CREATE TABLE "missed_questions" (
    user_id        BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    doc_hash       TEXT NOT NULL,
    text_key       TEXT NOT NULL,
    concept_key    TEXT NOT NULL,
    concept        TEXT NOT NULL,
    source         TEXT NOT NULL CHECK (source IN ('arena', 'quiz', 'exam')),
    question       TEXT NOT NULL,
    correct_answer TEXT NOT NULL,
    explanation    TEXT,
    missed_at      TEXT NOT NULL,
    PRIMARY KEY (user_id, doc_hash, text_key)
);

CREATE TABLE model_usage_daily (
    day             TEXT NOT NULL,
    provider        TEXT NOT NULL,
    model           TEXT NOT NULL,
    job             TEXT NOT NULL,
    calls           BIGINT NOT NULL DEFAULT 0,
    tokens_in       BIGINT NOT NULL DEFAULT 0,
    tokens_out      BIGINT NOT NULL DEFAULT 0,
    cost_micro_usd  BIGINT NOT NULL DEFAULT 0,
    fallbacks       BIGINT NOT NULL DEFAULT 0,
    byok_calls      BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (day, provider, model, job)
);

CREATE TABLE payment_events (
    id                TEXT PRIMARY KEY,
    provider          TEXT NOT NULL,
    event             TEXT NOT NULL,
    subscription_id   TEXT,
    received_at       TEXT NOT NULL
);

CREATE TABLE quizzes (
    id             TEXT PRIMARY KEY,                       -- the quiz_id handed to the client
    user_id        BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id     TEXT NOT NULL,                          -- the document the quiz was made from
    topic          TEXT NOT NULL,
    question_type  TEXT NOT NULL,
    questions_json TEXT NOT NULL,                          -- full questions incl. correct_answer + explanation (server only)
    question_count BIGINT NOT NULL,
    created_at     TEXT NOT NULL,
    finished_at    TEXT,                                   -- NULL until /quiz/finish; set exactly once
    correct_count  BIGINT,
    accuracy       DOUBLE PRECISION
);

CREATE TABLE quiz_answers (
    quiz_id     TEXT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
    question_id BIGINT NOT NULL,
    answer      TEXT NOT NULL,                             -- the option the user picked (first answer wins)
    correct     BIGINT NOT NULL,
    answered_at TEXT NOT NULL,
    PRIMARY KEY (quiz_id, question_id)
);

CREATE TABLE quiz_bank (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    doc_hash        TEXT NOT NULL,
    topic_key       TEXT NOT NULL,
    question_type   TEXT NOT NULL,
    text_key        TEXT NOT NULL,
    question_json   TEXT NOT NULL,
    model           TEXT,
    created_at      TEXT NOT NULL,
    UNIQUE (doc_hash, topic_key, question_type, text_key)
);

CREATE TABLE quiz_bank_served (
    user_id         BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    bank_id         BIGINT NOT NULL REFERENCES quiz_bank(id) ON DELETE CASCADE,
    served_at       TEXT NOT NULL,
    PRIMARY KEY (user_id, bank_id)
);

CREATE TABLE review_items (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    doc_hash     TEXT NOT NULL,
    item_key     TEXT NOT NULL,                                  -- normalised front text
    source       TEXT NOT NULL CHECK (source IN ('flashcard', 'arena', 'quiz', 'exam')),
    concept      TEXT,
    concept_key  TEXT,
    front        TEXT NOT NULL,
    back         TEXT NOT NULL,
    explanation  TEXT,
    state        BIGINT NOT NULL DEFAULT 1 CHECK (state IN (1, 2, 3)),   -- FSRS: 1 learning, 2 review, 3 relearning
    step         BIGINT,
    stability    DOUBLE PRECISION,
    difficulty   DOUBLE PRECISION,
    due          TEXT NOT NULL,                                  -- UTC, ISO seconds (string order = time order)
    last_review  TEXT,
    reps         BIGINT NOT NULL DEFAULT 0,
    lapses       BIGINT NOT NULL DEFAULT 0,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    UNIQUE (user_id, doc_hash, item_key)
);

CREATE TABLE review_logs (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    item_id      BIGINT NOT NULL REFERENCES review_items(id) ON DELETE CASCADE,
    rating       BIGINT NOT NULL CHECK (rating BETWEEN 1 AND 4),
    was_new      BIGINT NOT NULL DEFAULT 0,
    reviewed_at  TEXT NOT NULL,
    local_date   TEXT NOT NULL,
    duration_ms  BIGINT
);

CREATE TABLE reward_events (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    kind            TEXT NOT NULL,
    xp              BIGINT NOT NULL DEFAULT 0,
    coins           BIGINT NOT NULL DEFAULT 0,
    source_id       TEXT,
    idempotency_key TEXT NOT NULL UNIQUE,
    created_at      TEXT NOT NULL
);

CREATE TABLE sessions (
    id          TEXT PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at  TEXT DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
    expires_at  TEXT NOT NULL
);

CREATE TABLE subscriptions (
    id                    TEXT PRIMARY KEY,
    user_id               BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    provider              TEXT NOT NULL CHECK (provider IN ('razorpay', 'stub')),
    tier                  TEXT NOT NULL CHECK (tier IN ('scholar', 'sage', 'archmage')),
    period                TEXT NOT NULL CHECK (period IN ('month', 'year')),
    status                TEXT NOT NULL,
    short_url             TEXT,
    current_start         TEXT,
    current_end           TEXT,
    cancel_at_period_end  BIGINT NOT NULL DEFAULT 0,
    created_at            TEXT NOT NULL,
    updated_at            TEXT NOT NULL
);

CREATE TABLE usage_daily (
    user_id      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    day          TEXT NOT NULL,
    ai_calls     BIGINT NOT NULL DEFAULT 0,
    byok_calls   BIGINT NOT NULL DEFAULT 0,
    tokens_in    BIGINT NOT NULL DEFAULT 0,
    tokens_out   BIGINT NOT NULL DEFAULT 0,
    byok_tokens  BIGINT NOT NULL DEFAULT 0, cost_micro_usd BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, day)
);

CREATE TABLE user_achievements (
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    achievement_id TEXT NOT NULL REFERENCES achievements(achievement_id),
    unlocked_at_utc TEXT NOT NULL,
    PRIMARY KEY (user_id, achievement_id)
);

CREATE TABLE user_avatar (
    user_id     BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    equipped_json TEXT NOT NULL DEFAULT '{}',
    owned_json    TEXT NOT NULL DEFAULT '[]',
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
, champion_id TEXT
    CHECK (champion_id IS NULL OR champion_id IN ('kaien', 'asha', 'brak', 'mira', 'vex', 'thorne')), champion_set_at TEXT);

CREATE TABLE user_buffs (
    user_id     BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    buffs_json  TEXT NOT NULL DEFAULT '{}',
    updated_at  TEXT NOT NULL
);

CREATE TABLE user_inventory (
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    item_id     TEXT NOT NULL,
    quantity    BIGINT NOT NULL DEFAULT 1,
    PRIMARY KEY (user_id, item_id)
);

CREATE TABLE user_plans (
    user_id      BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    tier         TEXT NOT NULL CHECK (tier IN ('apprentice', 'scholar', 'sage', 'archmage')),
    source       TEXT NOT NULL CHECK (source IN ('invite', 'admin', 'subscription')),
    source_ref   TEXT,
    started_at   TEXT NOT NULL,
    expires_at   TEXT,
    updated_at   TEXT NOT NULL
);

CREATE TABLE user_progress (
    user_id     BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    total_xp    BIGINT NOT NULL DEFAULT 0,
    current_level BIGINT NOT NULL DEFAULT 1,
    coins       BIGINT NOT NULL DEFAULT 0,

    streak_days BIGINT NOT NULL DEFAULT 0,
    last_active_utc TEXT,
    streak_freezes BIGINT NOT NULL DEFAULT 0,

    total_arena_rounds      BIGINT NOT NULL DEFAULT 0,
    total_bosses_defeated   BIGINT NOT NULL DEFAULT 0,
    total_quizzes_completed BIGINT NOT NULL DEFAULT 0,
    total_chat_questions    BIGINT NOT NULL DEFAULT 0,
    total_chat_bundles      BIGINT NOT NULL DEFAULT 0,
    total_notes_generated   BIGINT NOT NULL DEFAULT 0,
    total_flashcards_studied  BIGINT NOT NULL DEFAULT 0,
    best_quiz_accuracy        BIGINT NOT NULL DEFAULT 0,
    nightmare_bosses_defeated BIGINT NOT NULL DEFAULT 0,

    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);

